\label{thm:nec_suf_well_posedness_intro}
Let $A\in \mathbb{R}^{m\times n}$ be a linear operator and $f:\mathbb{R}^n \rightarrow \mathbb{R} \cup \{\infty\}$ be a convex piecewise linear function, i.e., $f(\bm{x}) = \max_{i = 1, \dots k}\{\bm{v}_i^T\bm{x} + w_i\} + \chi_{\mathbf{P}}(\bm{x})$ with $\bm{v}_i \in \mathbb{R}^n$, $w_i \in \mathbb{R}$, $\mathbf{P}$ a polyhedral set and $\chi_{\mathbf{P}}(\bm{x})$ is zero if $\bm{x} \in \mathbf{P}$ and infinite otherwise. Furthermore, assume that $\dim(\operatorname{dom}(f)) = n$, where $\operatorname{dom}(f)$ is the effective domain of $f$, i.e., the points $\bm{x}$ in the domain for which $f(\bm{x})$ is finite. Then, the sparse regularized linear least squares problem
\begin{equation}\label{eq:linear_least_squares}
    \operatorname*{argmin}_{\bm{x} \in \mathbb{R}^n}\left\{\frac{1}{2}\|A\bm{x} - \bm{b}\|_2^2 + f(\bm{x})\right\},
\end{equation}
is well-posed if and only if $\operatorname{row}(A) \cap \partial f(\bm{x}) \neq \emptyset$ for $\bm{x} \in \mathbb{R}^n$ implies that $\dim(\partial f(\bm{x})) \geq \operatorname{nullity}(A)$, where $\operatorname{row}(A)$ is the row space of $A$, $\operatorname{nullity}(A)$ is the dimension of the null space of $A$ and $\partial f(\bm{x})$ is the subdifferential of $f$ at $\bm{x}$.

\label{def:piecewise_linear_function}
A function $f: \mathbb{R}^n \rightarrow \mathbb{R} \cup \{\infty\}$ is called convex piecewise linear if any of the following equivalent conditions hold:
\begin{itemize}
    \par\hangindent 40\p@ the epigraph $\operatorname{epi}(f):= \{(\bm{x}, t) \in \mathbb{R}^n \times \mathbb{R} \,|\, f(\bm{x}) \leq t \}$ is a polyhedral set.
    \par\hangindent 40\p@ the domain of $f$ is a polyhedral set and it is the maximum over finitely many affine functions, i.e., $f(\bm{x}) = \max_{i = 1, \dots k}\{\bm{v}_i^T\bm{x} + w_i\} + \chi_{\mathbf{P}}(\bm{x})$ with $\bm{v}_i \in \mathbb{R}^n$, $w_i \in \mathbb{R}$, $\mathbf{P}$ a polyhedral set.
    \par\hangindent 40\p@ $f$ is convex and the domain of $f$ can be covered by finitely many polyhedral sets, such that the restriction of $f$ to any of these polyhedral sets is an affine function.
\end{itemize}

\label{def:polyhedral_complex}
We call a set $\mathcal{E} \subset \mathcal{P}(\mathbb{R}^n)$, where $\mathcal{P}(\mathbb{R}^n)$ denotes the power-set of $\mathbb{R}^n$, a polyhedral complex if the following holds:
\begin{itemize}
    \par\hangindent 40\p@ All $\mathbf{E} \in \mathcal{E}$ are polyhedral.
    \par\hangindent 40\p@ If $\mathbf{F}$ is a non-empty face of $\mathbf{E} \in \mathcal{E}$, then $\mathbf{F} \in \mathcal{E}$.
    \par\hangindent 40\p@ If $\mathbf{E}, \mathbf{F} \in \mathcal{E}$ have common intersection, then $\mathbf{E} \cap \mathbf{F}$ is a face of both $\mathbf{E}$ and $\mathbf{F}$.
\end{itemize}
Note that compared to the conventional definition of a polyhedral complex, we do not require the empty set to be in $\mathcal{E}$.

\label{def:domain_complex}
Let $f : \mathbb{R}^{n} \rightarrow \mathbb{R} \cup \{\infty\}$ be convex piecewise linear. Define the lower faces of the epigraph of $f$ as
\begin{equation*}
    \bar{\mathcal{F}}_f := \{\mathbf{F}\ \,\text{\normalfont is a face of}\ \operatorname{epi}(f)\,|\, \mathbf{F} \neq \emptyset\ \,\text{\normalfont and}\ \dim(\mathbf{F}) \neq n + 1\}.
\end{equation*}

Let $P : \mathbb{R}^{n+1} \rightarrow \mathbb{R}^n$ be the linear projection map $P(\bm{x}, \bm{t}) = \bm{x}$ and define the primal complex of $f$ as
\begin{equation*}
    \mathcal{F}_f := P\bar{\mathcal{F}}_f = \{P\bar{\mathbf{F}}\,|\, \bar{\mathbf{F}} \in \bar{\mathcal{F}}_f\}.
\end{equation*}

\label{prop:constant_subdifferential}
Let $f : \mathbb{R}^{n} \rightarrow \mathbb{R} \cup \{\infty\}$ be convex piecewise linear. Each polyhedral set $\mathbf{F} \in \mathcal{F}_f$ can be characterized as follows. Let $\bm{x} \in \operatorname{relint}(\mathbf{F})$ be arbitrary, then the relative interior $\operatorname{relint}(\mathbf{F})$ consists precisely of all $\bm{y}\in \mathbb{R}^n$ for which $\partial f(\bm{x}) = \partial f(\bm{y})$.

The constant subdifferential corresponding to $\operatorname{relint}(\mathbf{F})$ will be denoted by $\partial f_{\mathbf{F}}$.

\label{def:subdifferential_complex}
Let $f : \mathbb{R}^{n} \rightarrow \mathbb{R} \cup \{\infty\}$ be convex piecewise linear. Define the corresponding dual complex as 
\begin{equation*}
    \mathcal{F}_f^\star := \{\partial f_\mathbf{F}\,|\, \mathbf{F} \in \mathcal{F}_f\} = \{\partial f(\bm{x})\,|\, \bm{x} \in \mathbb{R}^n\}.
\end{equation*}

\label{prop:duality_of_complexes}
Let $f : \mathbb{R}^{n} \rightarrow \mathbb{R} \cup \{\infty\}$ be convex piecewise linear. Then,
\begin{equation*}
    \left(\mathcal{F}_{f^\star}, \mathcal{F}_{f^\star}^\star\right) = \left(\mathcal{F}_f^\star, \mathcal{F}_f\right).
\end{equation*}

\label{lemma:properties_duality_of_complexes_2}
Let $f : \mathbb{R}^{n} \rightarrow \mathbb{R} \cup \{\infty\}$ be convex piecewise linear. Let $\mathbf{F} \in \mathcal{F}_f$ with corresponding $\partial f_{\mathbf{F}} \in \mathcal{F}_f^\star$, then the following holds:
\begin{enumerate}[label=\roman*]
    \par\hangindent 40\p@ $\dim(\mathbf{F}) + \dim(\partial f_{\mathbf{F}}) = n$ .\label{lemma:duality_dimensions}
    \par\hangindent 40\p@ $\partial f_{\mathbf{F}} \bot \mathbf{F}$, i.e., $(\partial f_{\mathbf{F}} - \partial f_{\mathbf{F}})^T(\mathbf{F} - \mathbf{F}) = \{\bm{0}\}$. \label{lemma:duality_orthogonal}
    \par\hangindent 40\p@ $\mathbf{F} + \partial f_{\mathbf{F}}^\bot \in \operatorname{aff}(\mathbf{F})$. \label{lemma:duality_orthogonal_2}
\end{enumerate}

(\ref{lemma:duality_dimensions}) Follows from the normal cone construction.

(\ref{lemma:duality_orthogonal}) Let $\bm{x}, \bm{x}' \in \mathbf{F}$ and $\bm{y}, \bm{y}' \in \partial f_{\mathbf{F}}$, then
\begin{equation*}
    (\bm{y} - \bm{y}')^T(\bm{x} - \bm{x}') = \bm{y}^T\bm{x} + \bm{y}'^T\bm{x}' - \bm{y}'^T\bm{x} - \bm{y}^T\bm{x}'. 
\end{equation*}
By conjugacy, $\bm{y}^T\bm{x} = f^\star(\bm{y}) + f(\bm{x})$ and similarly for the other terms. All thee terms will cancel out resulting in
\begin{equation*}
    (\bm{y} - \bm{y}')^T(\bm{x} - \bm{x}') = \bm{0}.
\end{equation*}

(\ref{lemma:duality_orthogonal_2}) Follows from properties \ref{lemma:duality_dimensions} and \ref{lemma:duality_orthogonal}.

\hfill$\square$

\label{lem:subdifferential_orthogonal_level_set}
Let $f: \mathbb{R}^{n} \rightarrow \mathbb{R} \cup \{\infty\}$ be convex piecewise linear. For every $\mathbf{L} \in \mathcal{L}_f(c)$ with $c\in\mathbb{R}$, let $\bm{x}\in\operatorname{relint}(\mathbf{L})$, then $\partial f(\bm{x})\bot \mathbf{L}$, i.e., $\partial f(\bm{x})^T(\mathbf{L}-\mathbf{L}) = \{\bm{0}\}$.

Particularly, $\mathbf{L} + \partial f(\bm{x})^\bot \in \operatorname{aff}(\mathbf{L})$.

Let $\bm{y}\in \partial f(\bm{x})$ and $\bm{v}, \bm{w} \in \mathbf{L}$, then by conjugacy, and $\mathbf{L}$ being a level set,
\begin{equation*}
    \bm{y}^T(\bm{v} - \bm{w}) = f^\star(\bm{y}) - f^\star(\bm{y}) + f(\bm{v}) - f(\bm{w}) = \bm{0}.
\end{equation*}
\hfill$\square$

\label{prop:two_solutions_large_codimension}
Let $f: \mathbb{R}^{n} \rightarrow \mathbb{R} \cup \{\infty\}$ be convex piecewise linear such that $\dim(\operatorname{dom}(f)) = n$ and  $A \in \mathbb{R}^{m\times n}$. 
If there exist distinct $\bm{x}, \bm{y} \in \mathbb{R}^n$ such that $\bm{x} - \bm{y} \in \operatorname{Null}(A)$ and $\operatorname{row}(A) \cap \partial f(\bm{x}) \cap \partial f(\bm{y}) \neq \emptyset$, then there exist $\mathbf{F} \in \mathcal{F}_f$ such that $\bm{x},\bm{y}\in \mathbf{F}$ and $\operatorname{codim}(\partial f_{\mathbf{F}}) > \operatorname{rank}(A)$.

\label{def:smooth_data_fidelity}
We call $D : \mathbb{R}^m \times \mathbb{R}^m \rightarrow \mathbb{R}$ a smooth data fidelity function if the following conditions hold:
\begin{itemize}
    \par\hangindent 40\p@ The map $\bm{z} \mapsto D(\bm{z}, \bm{b})$ is strictly convex and differentiable for all $\bm{b} \in \mathbb{R}^m$,
    \par\hangindent 40\p@ The map $\bm{b} \mapsto \nabla_{\bm{z}} D(\bm{z}, \bm{b}) : \mathbb{R}^m \rightarrow \mathbb{R}^m$ is bijective for all $\bm{z} \in \mathbb{R}^m$,
\end{itemize}
where $\nabla_{\bm{z}} D$ denotes the gradient of $D$ with respect to the first variable.

\label{prop:bregman_divergence}
Consider the Bregman divergence associated to a continuously differentiable convex function $\phi: \mathbb{R}^m \rightarrow \mathbb{R}$, i.e., $D_\phi(\bm{z}, \bm{b}) = \phi(\bm{z}) - \phi(\bm{b}) - \nabla \phi(\bm{b})^T(\bm{z} - \bm{b})$.
Assume that $\phi$ is strictly convex and $\operatorname{range}(\nabla \phi) = \mathbb{R}^m$, then $D_\phi$ is a smooth data fidelity function.

The Bregman divergence is always convex in its first argument. The gradient of the Bregman divergence with respect to the first argument is
\begin{equation*}
    \nabla_{\bm{z}}D_\phi(\bm{z}, \bm{b}) = \nabla \phi(\bm{z}) - \nabla \phi(\bm{b}),
\end{equation*}
with, for fixed $\bm{z} \in \mathbb{R}^m$, the inverse map
\begin{equation*}
    \bm{v} \mapsto [\nabla \phi]^{-1}(\nabla \phi(\bm{z}) - \bm{v}).
\end{equation*}
\hfill$\square$

\label{def:solution_set_map}
Let $D : \mathbb{R}^m \times \mathbb{R}^m \rightarrow \mathbb{R}$ be any function, $A\in \mathbb{R}^{m\times n}$ be a linear operator and $f:\mathbb{R}^n \rightarrow \mathbb{R} \cup \{\infty\}$ be a proper convex lower semi-continuous function. Define the corresponding solution map $\mathbf{S}^D_{A,f} : \mathbb{R}^{m} \rightarrow \mathcal{P}(\mathbb{R}^n)$ by
\begin{equation*}
    \mathbf{S}^D_{A,f}(\bm{b}) := \operatorname*{argmin}_{\bm{x} \in \mathbb{R}^n} \left\{D(A\bm{x},\bm{b}) + f(\bm{x})\right\}.
\end{equation*}

\label{lem:range_condition}
Let $f:\mathbb{R}^n \rightarrow \mathbb{R} \cup \{\infty\}$ be a proper convex lower semi-continuous function and $D : \mathbb{R}^m \times \mathbb{R}^m \rightarrow \mathbb{R}$ a smooth data fidelity function. Then, 
\begin{equation*}
    \bm{x} \in \operatorname{range}(\mathbf{S}^D_{A,f}) \quad \,\text{\normalfont if and only if} \quad \operatorname{row}(A) \cap \partial f(\bm{x}) \neq \emptyset.
\end{equation*}

\label{prop:range_condition_piecewise_linear}
Let $f:\mathbb{R}^n \rightarrow \mathbb{R} \cup \{\infty\}$ be a convex piecewise linear function and $D : \mathbb{R}^m \times \mathbb{R}^m \rightarrow \mathbb{R}$ a smooth data fidelity function. For any $\mathbf{F} \in \mathcal{F}_f$ we have 
\begin{equation*}
    \mathbf{F} \subseteq \operatorname{range}(\mathbf{S}^D_{A,f}) \quad \,\text{\normalfont if and only if} \quad \operatorname{row}(A) \cap \partial f_{\mathbf{F}} \neq \emptyset.
\end{equation*}

By Lemma ef{lem:range_condition}, $\operatorname{row}(A) \cap \partial f_{\mathbf{F}} 
eq \emptyset$ if and only if $\operatorname{relint}(\mathbf{F}) \subseteq \operatorname{range}(\mathbf{S}_{A,f})$. If $\mathbf{H} \in \mathcal{F}_f$ is a face of $\mathbf{F}$, then by duality also $\operatorname{row}(A) \cap \partial f_{\mathbf{H}} \supseteq \operatorname{row}(A) \cap \partial f_{\mathbf{F}} 
eq \emptyset$. Therefore, also $\operatorname{relint}(\mathbf{H}) \subseteq \operatorname{range}(\mathbf{S}_{A,f})$. Because $\mathbf{F}$ is the union of the relative interiors of all of its faces, we obtain $\operatorname{row}(A) \cap \partial f_{\mathbf{F}} 
eq \emptyset$ if and only if $F \subseteq \operatorname{range}(\mathbf{S}_{A,f})$.
\hfill$\square$

\label{cor:range_solution_set}
Let $f:\mathbb{R}^n \rightarrow \mathbb{R} \cup \{\infty\}$ be a convex piecewise linear function and $D : \mathbb{R}^m \times \mathbb{R}^m \rightarrow \mathbb{R}$ a smooth data fidelity function. Then, there exists a polyhedral subcomplex $\mathcal{E} \subseteq \mathcal{F}_f$, such that 
\begin{equation*}
    \operatorname{range}(\mathbf{S}^D_{A, f}) = \bigcup_{\mathbf{F} \in \mathcal{E}}\mathbf{F}.
\end{equation*}

\label{lem:equal_fit}
Let $f:\mathbb{R}^n \rightarrow \mathbb{R} \cup \{\infty\}$ be a proper convex lower semi-continuous function and let $D: \mathbb{R}^m\times \mathbb{R}^m \rightarrow \mathbb{R}$ be strictly convex in its first argument.
For every $\bm{b} \in \mathbb{R}^m$, if $\bm{x}, \bm{y} \in \mathbf{S}^D_{A,f}(\bm{b})$, then $A\bm{x} = A\bm{y}$ and $f(\bm{x}) = f(\bm{y})$.

Let $\bm{x}, \bm{y} \in \mathbf{S}_{A, f}^{D}(\bm{b})$ distinct, then by Lemma \ref{lem:equal_fit} $A\bm{x} = A\bm{y}$. Furthermore, by optimality we get
\begin{equation*}
    -A^T\nabla_{\bm{z}}D(A\bm{x}, \bm{b}) \in \partial f(\bm{x}) \quad \text{and} \quad -A^T\nabla_{\bm{z}}D(A\bm{y}, \bm{b}) \in \partial f(\bm{y}).
\end{equation*}
Therefore,
\begin{equation*}
    -A^T\nabla_{\bm{z}}D(A\bm{x}, \bm{b}) \in \partial f(\bm{x}) \quad \text{and} \quad -A^T\nabla_{\bm{z}}D(A\bm{x}, \bm{b}) \in \partial f(\bm{y}),
\end{equation*}
hence $\operatorname{row}(A)\cap \partial f(\bm{x}) \cap \partial f(\bm{y}) \neq \emptyset$. The conclusion follows directly from Proposition \ref{prop:two_solutions_large_codimension}.
\hfill$\square$

Let $\bm{\alpha},\bm{\beta} \in [S^D_{A,f}]^{-1}(\mathbf{F})$ such that $\bm{x} = S^D_{A,f}(\bm{\alpha}) \in \mathbf{F}$ and $\bm{y} = S_{A,f}(\bm{\beta}) \in \mathbf{F}$. Then,
\begin{equation*}
    A^T\Sigma(\bm{\alpha} - A\bm{x}) \in \partial f_{\mathbf{F}}\quad \text{and} \quad A^T\Sigma(\bm{\beta} - A\bm{y}) \in \partial f_{\mathbf{F}}.
\end{equation*}
Let $\lambda \in [0, 1]$, then by convexity of $\partial f_{\mathbf{F}}$ we obtain,
\begin{equation*}
    A^T\Sigma([\lambda\bm{\alpha} + (1-\lambda)\bm{\beta}] - A[\lambda\bm{x} + (1-\lambda)\bm{y}])\in \partial f_{\mathbf{F}}.
\end{equation*}
Thus, for all $\alpha,\beta \in [S^D_{A,f}]^{-1}(\mathbf{F})$ and $\lambda \in [0,1]$, we have
\begin{equation*}
    S_{A, f}(\lambda\bm{\alpha} + (1-\lambda)\bm{\beta}) = \lambda S_{A,f}(\bm{\alpha}) + (1-\lambda)S_{A,f}(\bm{\beta}),
\end{equation*}
therefore, $S_{A,f}(\mathbf{F})$ is convex and $[S^D_{A,f}]^{-1}\big|_{[S^D_{A,f}]^{-1}(\mathbf{F})}$ is affine.
Because $[S^D_{A,f}]^{-1}\big|_{[S^D_{A,f}]^{-1}(\mathbf{F})}$ is continuous and $\mathbf{F}$ is closed, the set $[S^D_{A,f}]^{-1}(\mathbf{F})$ is closed.
\hfill$\square$

\label{prop:l0_minimization}
For any $B\in \mathbb{R}^{k\times n}$ and $\bm{y} \in \mathbb{R}^{k}$, there exists $A \in \mathbb{R}^{m\times n}$ and $f(\bm{x}) = \chi_{\|\cdot\|_\infty \leq 1}(\bm{x}) - \bm{v}^T\bm{x}$ for some $\bm{v} \in \mathbb{R}^n$, such that the $l_0$ minimization problem
\begin{equation}\label{eq:l0_minimization}
    \min_{\bm{z}}\{\|\bm{z}\|_0 \,|\, B\bm{z} = \bm{y}\},
\end{equation}
is equivalent to
\begin{equation}\label{eq:ill-posedness_minimization}
    \min_{\mathbf{F}}\{\dim(\partial f_{\mathbf{F}})\,|\, \partial f_{\mathbf{F}} \in \mathcal{F}_f^\star \text{ and } \operatorname{row}(A) \cap \partial f_{\mathbf{F}} \neq \emptyset\}.
\end{equation}

Similarly, the nonnegative $l_0$ minimization problem
\begin{equation}\label{eq:nnl0_minimization}
    \min_{\bm{z}}\{\|\bm{z}\|_0 \,|\, B\bm{z} = \bm{y} \text{ and } \bm{z} \in \mathbb{R}^{n}_{\geq 0}\},
\end{equation}
can be transformed into \eqref{eq:ill-posedness_minimization} for $f(\bm{x}) = \chi_{\bm{v} - \mathbb{R}^{n}_{\geq 0}}(\bm{x}) - \bm{v}^T\bm{x}$ for some $\bm{v} \in \mathbb{R}^n$.

Let $B\in \mathbb{R}^{k\times n}$ and $\bm{y} \in \mathbb{R}^k$. Let $\bm{v} \in \mathbb{R}^n$ satisfy $B\bm{v} = \bm{y}$ and define $\bm{z} = \bm{x} - \bm{v}$, then \eqref{eq:l0_minimization} is equivalent to
\begin{equation}\label{eq:l0_minimization_translated}
    \min_{\bm{x}}\{\|\bm{x} - \bm{v}\|_0 \,|\, B\bm{x} = \bm{0}\}.
\end{equation}
Now, let $A$ be a matrix such that $\operatorname{row}(A) = \operatorname{Null}(B)$, then $B\bm{x} = 0$ is equivalent to $\bm{x} \in \operatorname{row}(A)$.
Furthermore, note that $\|\bm{x} - \bm{v}\|_0 = \dim(\partial f(\bm{y}))$ when $f(\bm{x}) = \chi_{\|\cdot\|_\infty \leq 1}(\bm{x}) - \bm{v}^T\bm{x}$ and $\bm{x} \in \partial f(\bm{y})$. Thus, for these $A$ and $f$, problem \eqref{eq:l0_minimization_translated} is equivalent to,
\begin{equation*}
    \min_{\bm{x}}\{\dim(\partial f(\bm{y}))\,|\, \bm{x} \in \partial f(\bm{y})\text{ and }\bm{x} \in \operatorname{row}(A)\},
\end{equation*}
which is equivalent to \eqref{eq:ill-posedness_minimization}.

The argument for nonnegative $l_0$ minimization is similar.
\hfill$\square$

\label{cor:np_hard_minimization}
Solving
\begin{equation}
    \min\{\dim(\partial f_{\mathbf{F}})\,|\, \partial f_{\mathbf{F}} \in \mathcal{F}_f^\star \text{ and } \operatorname{row}(A) \cap \partial f_{\mathbf{F}} \neq \emptyset\},
\end{equation}
for convex piecewise linear functions $f$ is NP-hard.
